from scores import SCORES

def count_passing(scores, mark):
    count = 0
    for s in scores:
        if s >= mark:
            count = count + 1
    return count

def average(scores):
    total = 0
    for s in scores:
        total = total + s
    return total / len(scores)

def highest(scores):
    best = scores[0]
    for s in scores:
        if s > best:
            best = s
    return best

print("passed:", count_passing(SCORES, 50))
print("average:", average(SCORES))
print("highest:", highest(SCORES))
